using System;

namespace Realmkeeper.Domain.Identifiers
{
    /// <summary>
    /// Stable, GUID-based identifier. Never derived from display names.
    /// Generated by <see cref="Realmkeeper.Domain.Randomness.DeterministicGuid"/> during
    /// world generation/simulation so identical seeds reproduce identical identifiers.
    /// </summary>
    public readonly struct StructureId : IEquatable<StructureId>, IComparable<StructureId>
    {
        public Guid Value { get; }

        public StructureId(Guid value)
        {
            Value = value;
        }

        public static StructureId Empty => default;

        public bool IsEmpty => Value == Guid.Empty;

        /// <summary>Creates a random (non-deterministic) identifier. Use only outside simulation/generation.</summary>
        public static StructureId NewRandom() => new StructureId(Guid.NewGuid());

        public static StructureId Parse(string text) => new StructureId(Guid.Parse(text));

        public static bool TryParse(string text, out StructureId id)
        {
            if (Guid.TryParse(text, out var guid))
            {
                id = new StructureId(guid);
                return true;
            }

            id = Empty;
            return false;
        }

        public bool Equals(StructureId other) => Value.Equals(other.Value);

        public override bool Equals(object obj) => obj is StructureId other && Equals(other);

        public override int GetHashCode() => Value.GetHashCode();

        public int CompareTo(StructureId other) => Value.CompareTo(other.Value);

        public override string ToString() => Value.ToString("D");

        public static bool operator ==(StructureId left, StructureId right) => left.Equals(right);

        public static bool operator !=(StructureId left, StructureId right) => !left.Equals(right);
    }
}
